       alternate_names = ARRAY(SELECT DISTINCT unnest(alternate_names || '{"Margaret T. Evans","Margaret Turner-Evans"}'::text[]))
 WHERE id = 'eaa58900-095c-4449-b918-18915d6fe21c'
   AND full_name = 'Trustee Area 4, 2024 Committee To Re-Elect Margaret T. Evans For Inglewood Usd Board Of Education'
   AND NOT full_name_manual_override;
