 WHERE id = 'aacc9d89-f7bd-4de2-98b8-34f6875ebaaf' AND NOT alternate_names @> '{"Tina Wu Fredericks"}';
UPDATE essentials.politicians SET alternate_names = ARRAY(SELECT DISTINCT unnest(alternate_names || '{"Kimberly Kenne"}'::text[]))
 WHERE id = '820d81c8-4f1a-4a05-a739-98e1c1e35c56' AND NOT alternate_names @> '{"Kimberly Kenne"}';
UPDATE essentials.politicians SET alternate_names = ARRAY(SELECT DISTINCT unnest(alternate_names || '{"Michelle Richardson Bailey"}'::text[]))
 WHERE id = '5cbf44d9-91de-4fc9-b5f0-76e2ae236914' AND NOT alternate_names @> '{"Michelle Richardson Bailey"}';
